(()=>{const f=document.getElementById('compareEngine'),b=document.getElementById('compareLanguage'),load=document.getElementById('compareLoading');let lang='es';const tr={es:{title:'Compara dos claves de prueba.',lead:'Una herramienta secundaria, con el mismo modelo del analizador. Utiliza solo ejemplos que no protejan cuentas reales.',back:'Volver al analizador',note:'No se transfieren claves entre esta página y la portada. La comparación no acredita cómo se generó una contraseña.',loading:'Preparando el comparador…',error:'No se pudo cargar el comparador. Recarga la página.'},en:{title:'Compare two test passwords.',lead:'A secondary tool using the same analysis model. Use only examples that do not protect real accounts.',back:'Back to analyzer',note:'No passwords are transferred between this page and the home page. Comparison cannot verify how a password was generated.',loading:'Preparing the comparison…',error:'Could not load the comparison. Reload this page.'}};
function apply(){document.documentElement.lang=lang;b.textContent=lang==='es'?'ES / EN':'EN / ES';document.querySelectorAll('[data-compare]').forEach(e=>e.textContent=tr[lang][e.dataset.compare]);f.contentWindow?.postMessage({channel:'securex-compare',type:'language',language:lang},'*');}b.addEventListener('click',()=>{lang=lang==='es'?'en':'es';apply();});addEventListener('message',e=>{if(e.source!==f.contentWindow||e.origin!=='null'||e.data?.channel!=='securex-compare')return;const d=e.data;if(d.type==='layout'&&Number.isFinite(d.height)&&d.height>100&&d.height<3000)f.style.height=d.height+'px';if(d.type==='ready'){load.hidden=true;apply();}});f.srcdoc=window.SecurexComparisonHTML;delete window.SecurexComparisonHTML;setTimeout(()=>{if(!load.hidden)load.textContent=tr[lang].error;},15000);apply();})();